-- IdeaDNA core. Apply once with `supabase db reset` or the SQL editor.
create extension if not exists pgcrypto;
create type public.tree_visibility as enum ('public','unlisted','private');
create type public.node_kind as enum ('root','extension','improvement','question','constraint','synthesis');
create type public.node_status as enum ('draft','published','archived');
create type public.edge_relation as enum ('extends','improves','challenges','synthesizes','depends_on');
create type public.synthesis_status as enum ('pending','completed','failed');
create type public.reaction_kind as enum ('insightful','buildable','needs_work','spark');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null unique check(username ~ '^[a-z0-9_]{3,30}$'),display_name text not null check(length(display_name) between 2 and 80),avatar_url text not null default '',bio text not null default '' check(length(bio)<=500),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.idea_trees(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 5 and 140),slug text not null unique check(slug ~ '^[a-z0-9-]{1,90}$'),description text not null check(length(description) between 20 and 500),root_node_id uuid,creator_id uuid not null references public.profiles(id),visibility public.tree_visibility not null default 'public',tags text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.idea_nodes(id uuid primary key default gen_random_uuid(),tree_id uuid not null references public.idea_trees(id) on delete cascade,parent_id uuid references public.idea_nodes(id),author_id uuid not null references public.profiles(id),title text not null check(length(title) between 5 and 140),content text not null check(length(content) between 20 and 10000),node_type public.node_kind not null,status public.node_status not null default 'published',contribution_score integer not null default 0,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((node_type='root' and parent_id is null) or (node_type<>'root' and parent_id is not null)));
alter table public.idea_trees add constraint root_node_fk foreign key(root_node_id) references public.idea_nodes(id) deferrable initially deferred;
create unique index one_root_per_tree on public.idea_nodes(tree_id) where node_type='root';
create table public.idea_edges(id uuid primary key default gen_random_uuid(),source_node_id uuid not null references public.idea_nodes(id) on delete cascade,target_node_id uuid not null references public.idea_nodes(id) on delete cascade,relation public.edge_relation not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(source_node_id,target_node_id),check(source_node_id<>target_node_id));
create table public.synthesis_requests(id uuid primary key default gen_random_uuid(),tree_id uuid not null references public.idea_trees(id) on delete cascade,source_node_a_id uuid not null references public.idea_nodes(id),source_node_b_id uuid not null references public.idea_nodes(id),result_node_id uuid references public.idea_nodes(id),requested_by uuid not null references public.profiles(id),prompt text not null default '',response jsonb,model text,status public.synthesis_status not null default 'pending',created_at timestamptz not null default now(),check(source_node_a_id<>source_node_b_id));
create table public.node_reactions(id uuid primary key default gen_random_uuid(),node_id uuid not null references public.idea_nodes(id) on delete cascade,user_id uuid not null references public.profiles(id),reaction_type public.reaction_kind not null,created_at timestamptz not null default now(),unique(node_id,user_id,reaction_type));
create table public.node_revisions(id uuid primary key default gen_random_uuid(),node_id uuid not null references public.idea_nodes(id) on delete cascade,editor_id uuid references public.profiles(id),title text not null,content text not null,status public.node_status not null,created_at timestamptz not null default now());
create index nodes_tree_idx on public.idea_nodes(tree_id);create index nodes_parent_idx on public.idea_nodes(parent_id);create index nodes_author_idx on public.idea_nodes(author_id);create index trees_creator_idx on public.idea_trees(creator_id);create index trees_tags_idx on public.idea_trees using gin(tags);create index edges_target_idx on public.idea_edges(target_node_id);create index edges_source_idx on public.idea_edges(source_node_id);create index reactions_node_idx on public.node_reactions(node_id);create index synthesis_user_time_idx on public.synthesis_requests(requested_by,created_at);create index revisions_node_idx on public.node_revisions(node_id);
create function public.touch_updated_at() returns trigger language plpgsql set search_path=public as $$begin new.updated_at=now();return new;end;$$;
create trigger touch_profiles before update on public.profiles for each row execute function public.touch_updated_at();create trigger touch_trees before update on public.idea_trees for each row execute function public.touch_updated_at();create trigger touch_nodes before update on public.idea_nodes for each row execute function public.touch_updated_at();
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(id,username,display_name) values(new.id,'maker_'||substr(md5(new.id::text),1,24),case when length(trim(coalesce(new.raw_user_meta_data->>'display_name','')))>=2 then left(trim(new.raw_user_meta_data->>'display_name'),80) else 'New contributor' end);return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.can_read_tree(t uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from idea_trees where id=t and (visibility in ('public','unlisted') or creator_id=auth.uid())); $$;
create function public.owns_tree(t uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from idea_trees where id=t and creator_id=auth.uid()); $$;
create function public.can_read_node(n uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from idea_nodes where id=n and can_read_tree(tree_id) and (status='published' or author_id=auth.uid() or owns_tree(tree_id))); $$;
alter table public.profiles enable row level security;alter table public.idea_trees enable row level security;alter table public.idea_nodes enable row level security;alter table public.idea_edges enable row level security;alter table public.synthesis_requests enable row level security;alter table public.node_reactions enable row level security;alter table public.node_revisions enable row level security;
create policy profile_read on public.profiles for select using(true);
create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy tree_read on public.idea_trees for select using(visibility in ('public','unlisted') or creator_id=auth.uid());
create policy tree_update on public.idea_trees for update to authenticated using(creator_id=auth.uid()) with check(creator_id=auth.uid());
create policy node_read on public.idea_nodes for select using(can_read_tree(tree_id) and (status='published' or author_id=auth.uid() or owns_tree(tree_id)));
create policy node_update on public.idea_nodes for update to authenticated using(author_id=auth.uid() or owns_tree(tree_id)) with check(author_id=auth.uid() or owns_tree(tree_id));
create policy edge_read on public.idea_edges for select using(can_read_node(source_node_id) and can_read_node(target_node_id));
create policy synthesis_read on public.synthesis_requests for select using(can_read_tree(tree_id));
create policy reaction_read on public.node_reactions for select using(can_read_node(node_id));
create policy reaction_insert on public.node_reactions for insert to authenticated with check(user_id=auth.uid() and can_read_node(node_id));
create policy reaction_update on public.node_reactions for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and can_read_node(node_id));
create policy reaction_delete on public.node_reactions for delete to authenticated using(user_id=auth.uid());
create policy revision_read on public.node_revisions for select using(can_read_node(node_id));
-- Narrow column grants make attribution, topology, scores, and AI provenance immutable to clients.
revoke all on public.profiles,public.idea_trees,public.idea_nodes,public.idea_edges,public.synthesis_requests,public.node_reactions,public.node_revisions from anon,authenticated;
grant select on public.profiles,public.idea_trees,public.idea_nodes,public.idea_edges,public.synthesis_requests,public.node_reactions,public.node_revisions to anon,authenticated;
grant update(display_name,username,avatar_url,bio) on public.profiles to authenticated;
grant update(title,description,visibility,tags) on public.idea_trees to authenticated;
grant update(title,content,status) on public.idea_nodes to authenticated;
grant insert(node_id,user_id,reaction_type),update(reaction_type),delete on public.node_reactions to authenticated;
create function public.record_revision() returns trigger language plpgsql security definer set search_path=public as $$begin if (old.title,old.content,old.status) is distinct from (new.title,new.content,new.status) then insert into node_revisions(node_id,editor_id,title,content,status) values(old.id,auth.uid(),old.title,old.content,old.status);end if;return new;end;$$;
create trigger save_revision before update on public.idea_nodes for each row execute function public.record_revision();
create function public.recount_reactions() returns trigger language plpgsql security definer set search_path=public as $$declare n uuid;begin n=coalesce(new.node_id,old.node_id);update idea_nodes set contribution_score=(select count(*) from node_reactions where node_id=n and reaction_type<>'needs_work') where id=n;return null;end;$$;
create trigger reaction_score after insert or update or delete on public.node_reactions for each row execute function public.recount_reactions();
create function public.create_idea_tree(payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare t idea_trees;n idea_nodes;begin if auth.uid() is null then raise exception 'Authentication required';end if;insert into idea_trees(id,title,slug,description,creator_id,visibility,tags) values(coalesce((payload->>'id')::uuid,gen_random_uuid()),payload->>'title',payload->>'slug',payload->>'description',auth.uid(),(payload->>'visibility')::tree_visibility,array(select jsonb_array_elements_text(payload->'tags'))) returning * into t;insert into idea_nodes(tree_id,author_id,title,content,node_type) values(t.id,auth.uid(),t.title,payload->>'content','root') returning * into n;update idea_trees set root_node_id=n.id where id=t.id;return to_jsonb(t);end;$$;
create function public.add_contribution(payload jsonb) returns jsonb language plpgsql security definer set search_path=public as $$declare n idea_nodes;p idea_nodes;rel edge_relation;k node_kind;begin if auth.uid() is null then raise exception 'Authentication required';end if;select * into p from idea_nodes where id=(payload->>'parent_id')::uuid and tree_id=(payload->>'tree_id')::uuid and status='published';if p.id is null or not can_read_tree(p.tree_id) then raise exception 'Parent is not accessible in this tree';end if;k=(payload->>'node_type')::node_kind;if k in ('root','synthesis') then raise exception 'Use the dedicated creation flow';end if;rel=case k when 'extension' then 'extends' when 'improvement' then 'improves' when 'question' then 'challenges' else 'depends_on' end;insert into idea_nodes(tree_id,parent_id,author_id,title,content,node_type,metadata) values(p.tree_id,p.id,auth.uid(),payload->>'title',payload->>'content',k,coalesce(payload->'metadata','{}')) returning * into n;insert into idea_edges(source_node_id,target_node_id,relation,created_by) values(p.id,n.id,rel,auth.uid());return to_jsonb(n);end;$$;
create function public.reserve_synthesis(p_tree uuid,p_a uuid,p_b uuid,p_prompt text) returns uuid language plpgsql security definer set search_path=public as $$declare r uuid;begin if auth.uid() is null or not can_read_tree(p_tree) then raise exception 'Not allowed';end if;perform id from profiles where id=auth.uid() for update;if (select count(*) from synthesis_requests where requested_by=auth.uid() and created_at>now()-interval '1 hour')>=8 then raise exception 'Synthesis rate limit';end if;if p_a=p_b or (select count(*) from idea_nodes where id in(p_a,p_b) and tree_id=p_tree and status='published')<>2 then raise exception 'Invalid synthesis sources';end if;if length(p_prompt)>2000 then raise exception 'Prompt too long';end if;insert into synthesis_requests(tree_id,source_node_a_id,source_node_b_id,requested_by,prompt) values(p_tree,p_a,p_b,auth.uid(),p_prompt) returning id into r;return r;end;$$;
-- Completion is reserved for the server's service-role client. Clients cannot forge AI provenance.
create function public.complete_synthesis(p_request uuid,p_blueprint jsonb,p_model text) returns jsonb language plpgsql security definer set search_path=public as $$declare r synthesis_requests;n idea_nodes;begin select * into r from synthesis_requests where id=p_request for update;if r.id is null or r.status<>'pending' then raise exception 'Request is not pending';end if;if not exists(select 1 from idea_trees where id=r.tree_id and (visibility in ('public','unlisted') or creator_id=r.requested_by)) or (select count(*) from idea_nodes where id in(r.source_node_a_id,r.source_node_b_id) and tree_id=r.tree_id and status='published')<>2 then raise exception 'Sources are no longer available';end if;insert into idea_nodes(tree_id,parent_id,author_id,title,content,node_type,metadata) values(r.tree_id,r.source_node_a_id,r.requested_by,p_blueprint->>'title',p_blueprint->>'concept','synthesis',jsonb_build_object('sources',jsonb_build_array(r.source_node_a_id,r.source_node_b_id),'blueprint',p_blueprint,'model',p_model)) returning * into n;insert into idea_edges(source_node_id,target_node_id,relation,created_by) values(r.source_node_a_id,n.id,'synthesizes',r.requested_by),(r.source_node_b_id,n.id,'synthesizes',r.requested_by);update synthesis_requests set status='completed',result_node_id=n.id,response=p_blueprint,model=p_model where id=r.id;return to_jsonb(n);end;$$;
create function public.fail_synthesis(p_request uuid) returns void language sql security definer set search_path=public as $$update synthesis_requests set status='failed' where id=p_request and requested_by=auth.uid() and status='pending';$$;
revoke execute on function public.handle_new_user(),public.touch_updated_at(),public.record_revision(),public.recount_reactions() from public;
revoke execute on function public.create_idea_tree(jsonb),public.add_contribution(jsonb),public.reserve_synthesis(uuid,uuid,uuid,text),public.complete_synthesis(uuid,jsonb,text),public.fail_synthesis(uuid) from public;
grant execute on function public.create_idea_tree(jsonb),public.add_contribution(jsonb),public.reserve_synthesis(uuid,uuid,uuid,text),public.fail_synthesis(uuid) to authenticated;
grant execute on function public.complete_synthesis(uuid,jsonb,text) to service_role;
-- Realtime honors SELECT policies; never use a service-role key in the browser.
alter publication supabase_realtime add table public.idea_trees,public.idea_nodes,public.node_reactions,public.synthesis_requests;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('avatars','avatars',true,2097152,array['image/png','image/jpeg','image/webp']) on conflict(id) do nothing;
create policy avatar_read on storage.objects for select using(bucket_id='avatars');
create policy avatar_upload on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy avatar_update on storage.objects for update to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);
create policy avatar_delete on storage.objects for delete to authenticated using(bucket_id='avatars' and (storage.foldername(name))[1]=auth.uid()::text);



